import {kernelContact} from "./drawings/kernel-contact.mjs";
import {validateNotches} from './drawings/notch-engine.mjs';
import {occDraw} from './drawings/occ-projection.mjs';
import init from 'replicad-opencascadejs';import wasm from 'replicad-opencascadejs/wasm?url';import * as R from 'replicad';
import {add,sub,mul,dot,cross,unit,area} from './adapter.mjs';
let ready;const setup=()=>ready??=init({locateFile:()=>wasm}).then(oc=>R.setOC(oc));
function prism(poly,depth,f){let pen=R.draw(poly[0]);for(let p of poly.slice(1))pen.lineTo(p);let plane=new R.Plane(f.origin,f.x,f.z);try{return pen.close().sketchOnPlane(plane).extrude(depth)}finally{plane.delete()}}
function localWorld(f,p){return add(f.origin,add(mul(f.x,p[0]),add(mul(f.y,p[1]),mul(f.z,p[2]))))}
function makeHardware(b){let shape;if(b.shape==='hex'){const x=unit(cross(b.axis,Math.abs(b.axis[0])<.8?[1,0,0]:[0,1,0])),y=unit(cross(b.axis,x));const poly=Array.from({length:6},(_,i)=>[b.diameter/2*Math.cos(i*Math.PI/3),b.diameter/2*Math.sin(i*Math.PI/3)]);shape=prism(poly,b.length,{origin:b.origin,x,y,z:b.axis});}else shape=R.makeCylinder(b.diameter/2,b.length,b.origin,b.axis);if(b.innerDiameter>0){const tool=R.makeCylinder(b.innerDiameter/2,b.length+2,sub(b.origin,b.axis),b.axis),next=shape.cut(tool);shape.delete();tool.delete();shape=next;}return shape;}
function makePart(p){let shape;if(p.plate&&!p.warnings.some(w=>w.startsWith('PLATE_BEVEL'))){let a=p.plate;shape=prism(a.outline,a.thickness,a.frame);}else{let [lo,hi]=p.extent,f={...p.frame,origin:localWorld(p.frame,[0,0,lo])};shape=prism(p.section.outer,hi-lo,f);for(let inner of p.section.inners){let tool=prism(inner,hi-lo+2,{...f,origin:sub(f.origin,f.z)});let next=shape.cut(tool);shape.delete();tool.delete();shape=next;}for(let cut of p.endPlanes){let x=Math.abs(cut.normal[0])<.8?[1,0,0]:[0,1,0],plane=new R.Plane(cut.origin,x,cut.normal),next;try{next=shape.cutPlane(plane,0,cut.keep)}finally{plane.delete()}if(!next){shape.delete();throw Error('חיתוך קצה מחק את כל החלק')}shape.delete();shape=next;}}
 for(const n of validateNotches(p)){const [u,v,z]=n.min,[U,V,Z]=n.max,tool=prism([[u,v],[U,v],[U,V],[u,V]],Z-z,{...p.frame,origin:localWorld(p.frame,[0,0,z])});const before=R.measureVolume(shape),next=shape.cut(tool),after=R.measureVolume(next);tool.delete();shape.delete();shape=next;if(before-after<.001)throw Error('מגרעת אינה מסירה חומר: '+n.id);const solids=shape.solids,count=solids.length;solids.forEach(x=>x.delete());if(count!==1)throw Error('מגרעת מחקה או פיצלה חלק: '+n.id);}
 for(let d of p.drills){let r=d.diameter/2,origin=sub(d.center,mul(d.axis,d.halfDepth)),depth=d.halfDepth*2,tool;
  if(d.slotExtra>0){let x=unit(sub(d.slotAxis,mul(d.axis,dot(d.slotAxis,d.axis)))),y=unit(cross(d.axis,x)),f={origin,x,y,z:d.axis},e=d.slotExtra/2,poly=[[-e,-r],[e,-r],[e,r],[-e,r]],a=R.makeCylinder(r,depth,sub(origin,mul(x,e)),d.axis),b=R.makeCylinder(r,depth,add(origin,mul(x,e)),d.axis),box=prism(poly,depth,f),joined=a.fuse(box);tool=joined.fuse(b);a.delete();b.delete();box.delete();joined.delete();}
  else tool=R.makeCylinder(r,depth,origin,d.axis);
  let before=R.measureVolume(shape),next=shape.cut(tool),after=R.measureVolume(next);shape.delete();tool.delete();shape=next;if(before-after<.001)throw Error(`הקדח ${d.id||''} אינו חותך חומר בחלק`);
 }
 if(R.measureVolume(shape)<.001){shape.delete();throw Error('נפח חלק ריק')};return shape;
}
function plateExpected(p){if(!p.plate||p.warnings.length)return null;let a=p.plate;return (area(a.outline)-a.holes.reduce((n,h)=>n+Math.PI*(h.diameter/2)**2+h.diameter*(h.slot??0),0))*a.thickness;}
self.onmessage=async({data})=>{let shapes=[],errors=[],rows=[];try{await setup();if(data.op==='weld-contact'){const contacts=kernelContact(R.getOC(),makePart,data.parts,data.pairs,(done,total)=>self.postMessage({id:data.id,progress:done/total,done,total}));self.postMessage({id:data.id,ok:true,contacts});return;}if(data.op==='drawing'){for(const p of data.parts){let shape=makePart(p);shapes.push({shape});}for(const b of data.hardware||[]){if(![...b.origin,...b.axis,b.diameter,b.length].every(Number.isFinite)||b.diameter<=0||b.length<=0)throw Error("נתוני גוף בורג לא תקינים");shapes.push({shape:makeHardware(b)});}const views=occDraw(R.getOC(),shapes.map(s=>s.shape),data.views,{steelCount:data.parts.length});self.postMessage({id:data.id,ok:true,views,hardwareCount:(data.hardware||[]).length});return;}for(let i=0;i<data.parts.length;i++){let p=data.parts[i];try{let shape=makePart(p),analyzer=new (R.getOC().BRepCheck_Analyzer)(shape.wrapped,true,false,true);try{if(!analyzer.IsValid()){shape.delete();throw Error('גוף CAD לא עבר בדיקת תקינות טופולוגית')}}finally{analyzer.delete()}let volume=R.measureVolume(shape),expected=plateExpected(p);if(expected!==null&&Math.abs(volume-expected)>Math.max(.01,expected*1e-7))throw Error('נפח הקדחים אינו תואם לשטח הפלטה — בדוק חורים חופפים או חור חורג');shapes.push({shape,name:`${p.mark} / ${p.id}`,color:p.plate?'#549aa9':'#7396aa'});let solids=shape.solids,faces=shape.faces,solidCount=solids.length,faceCount=faces.length;solids.forEach(s=>s.delete());faces.forEach(f=>f.delete());rows.push({id:p.id,mark:p.mark,volume,expected,warnings:p.warnings,solids:solidCount,faces:faceCount,mesh:data.mesh?shape.mesh({tolerance:.2,angularTolerance:.15}):undefined});}catch(e){errors.push({id:p.id,mark:p.mark,message:String(e.message??e)})}self.postMessage({id:data.id,progress:(i+1)/Math.max(1,data.parts.length),done:i+1,total:data.parts.length});}
 if(data.op==='step'&&errors.length)throw Error(`הייצוא נחסם: ${errors.length} חלקים לא עברו בדיקה`);let blob=data.op==='step'?R.exportSTEP(shapes,{unit:'MM',modelUnit:'MM'}):undefined,roundTrip;if(blob&&data.roundTrip){let imported=await R.importSTEP(blob);try{let volume=R.measureVolume(imported),expected=rows.reduce((n,r)=>n+r.volume,0);if(Math.abs(volume-expected)>Math.max(.01,expected*1e-6))throw Error('נפח STEP בקריאה חוזרת אינו תואם למקור');roundTrip={volume,expected,valid:true};}finally{imported.delete()}}self.postMessage({id:data.id,ok:true,rows,errors,blob,roundTrip});}catch(e){self.postMessage({id:data.id,ok:false,error:String(e.message??e),rows,errors})}finally{shapes.forEach(s=>{try{s.shape.delete()}catch{}})}};
